using System;using System.Collections.Generic;using System.IO;using System.Xml.Serialization;using ScreenDock;
class EyePresetTests{
 static void Main(){var events=new List<string>();var s=new PresetScreen{EyeEnabled=true,WarmStrength=100,Brightness=40};Action<int>w=x=>events.Add("warm"+x);Action r=()=>events.Add("restore");Action<int>b=x=>events.Add("brightness"+x);MainForm.ApplyPresetSettings(s,()=>false,w,r,b);if(String.Join(",",events)!="warm100,brightness40")throw new Exception("warm ordering");events.Clear();s.EyeEnabled=false;MainForm.ApplyPresetSettings(s,()=>true,w,r,b);if(String.Join(",",events)!="restore,brightness40")throw new Exception("restore before brightness");events.Clear();s.EyeEnabled=null;MainForm.ApplyPresetSettings(s,()=>true,w,r,b);if(String.Join(",",events)!="brightness40")throw new Exception("legacy changes eye state");var ser=new XmlSerializer(typeof(PresetScreen));using(var ms=new MemoryStream()){s.EyeEnabled=true;ser.Serialize(ms,s);ms.Position=0;var x=(PresetScreen)ser.Deserialize(ms);if(x.EyeEnabled!=true||x.WarmStrength!=100)throw new Exception("roundtrip");}Console.WriteLine("PASS: eye enable/restore ordering, legacy null preserves state, XML roundtrip; fake hardware callbacks only.");}}
